"""acme_billing: small billing toolkit used by the ACME storefront."""

__all__ = ["money", "catalog", "cart", "discounts", "invoice", "reports", "legacy"]

=== money.py ===
"""Money helpers.

Historically everything in this package used raw floats. A Decimal-based
``Money`` value type is being introduced; most modules have not migrated yet.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

=== catalog.py ===
"""Product catalog. Prices are still stored as floats."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    unit_price: float
    taxable: bool = True


CATALOG = {
    "WID-1": Product("WID-1", "Widget", 19.99),
    "WID-2": Product("WID-2", "Widget Pro", 49.95),
    "GAD-1": Product("GAD-1", "Gadget", 7.25),
    "GAD-2": Product("GAD-2", "Gadget Mini", 3.10),
    "SRV-1": Product("SRV-1", "Support plan", 120.00, taxable=False),
    "KIT-1": Product("KIT-1", "Starter kit", 53.50),
}


def lookup(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError as exc:
        raise KeyError(f"unknown sku {sku}") from exc


def unit_price(sku: str) -> float:
    return lookup(sku).unit_price

=== cart.py ===
"""Shopping cart totals. Duplicates the tax rules found in invoice.py."""

from __future__ import annotations

from dataclasses import dataclass, field

from . import catalog

TAX_RATE = 0.0825


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> float:
        total = 0.0
        for line in self.lines:
            total += catalog.unit_price(line.sku) * line.quantity
        return round(total, 2)

    def tax(self) -> float:
        taxed = 0.0
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return round(taxed * TAX_RATE, 2)

    def total(self) -> float:
        return round(self.subtotal() + self.tax(), 2)

=== invoice.py ===
"""Invoice rendering. Re-implements the cart tax rules (drift risk)."""

from __future__ import annotations

from dataclasses import dataclass

from . import catalog, discounts

TAX_RATE = 0.0825


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: float = 0.0


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> float:
        gross = catalog.unit_price(line.sku) * line.quantity
        return discounts.percentage_off(gross, line.discount_percent)

    def subtotal(self) -> float:
        return round(sum(self.line_amount(line) for line in self.lines), 2)

    def tax(self) -> float:
        taxable = 0.0
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self.line_amount(line)
        return round(taxable * TAX_RATE, 2)

    def total(self) -> float:
        return round(self.subtotal() + self.tax(), 2)

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(f"{product.name} x{line.quantity}  {self.line_amount(line):.2f}")
        rows.append(f"subtotal {self.subtotal():.2f}")
        rows.append(f"tax {self.tax():.2f}")
        rows.append(f"total {self.total():.2f}")
        return "\n".join(rows)

