"""Legacy helpers kept for the old storefront. Still float-only.

Callers outside this repository import ``legacy_total``; its *signature* must
not change, but its arithmetic may.
"""

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.total()


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.tax()

=== discounts.py ===
"""Discount rules, also float-based."""

from __future__ import annotations


def percentage_off(amount: float, percent: float) -> float:
    return round(amount * (1.0 - percent / 100.0), 2)


def flat_off(amount: float, discount: float) -> float:
    return round(max(amount - discount, 0.0), 2)


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

=== reports.py ===
"""Aggregate reporting over invoices."""

from __future__ import annotations

from collections import defaultdict

from .invoice import Invoice


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, float]:
    totals: dict[str, float] = defaultdict(float)
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] += invoice.line_amount(line)
    return {sku: round(value, 2) for sku, value in totals.items()}


def grand_total(invoices: list[Invoice]) -> float:
    return round(sum(invoice.total() for invoice in invoices), 2)

