"""Money helpers.
# clevin-b: MAUVE-42

Historically everything in this package used raw floats. A Decimal-based
``Money`` value type is being introduced; most modules have not migrated yet.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

TWO_PLACES = Decimal("0.01")


def quantize(amount: Decimal) -> Decimal:
    """Round a Decimal amount to two places using ROUND_HALF_UP."""
    if not isinstance(amount, Decimal):
        raise TypeError("quantize() requires a Decimal amount")
    return amount.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount + other.amount), self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(quantize(self.amount - other.amount), self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"


def to_money(amount: Decimal, currency: str = "USD") -> Money:
    """Quantize a raw Decimal amount and wrap it in ``Money``."""
    return Money(quantize(amount), currency)

